do $$ declare v_governance_ready integer; begin select count(*) into v_governance_ready from runtime_config_inventory_governance where configuration_key in ('cluster.delivery-router.enabled','cluster.delivery-router.prefer-local','cluster.delivery-router.reject-duplicate-agents','cluster.delivery-router.request-timeout-ms','cluster.delivery-router.require-synced-remote-state','cluster.sync.enabled','cluster.sync.interval-ms','cluster.sync.max-agents-per-node','cluster.sync.max-events-per-node','cluster.sync.remote-state-ttl-ms','cluster.sync.request-timeout-ms') and status='MIGRATION_READY' and classified_by is not null and owner_reviewed_by is not null and architecture_approved_by is not null and migration_authorized_by='v41-c3r2j-cluster-sync-delivery-router-consumer-closure'; if v_governance_ready<>11 then raise exception 'C3R2J_GOVERNANCE_LIFECYCLE_INCOMPLETE expected=11 actual=%',v_governance_ready; end if; end $$;

do $$ declare v_ready integer; begin
select count(*) into v_ready from runtime_config_definitions where definition_key in ('cluster.delivery-router.enabled','cluster.delivery-router.prefer-local','cluster.delivery-router.reject-duplicate-agents','cluster.delivery-router.request-timeout-ms','cluster.delivery-router.require-synced-remote-state','cluster.sync.enabled','cluster.sync.interval-ms','cluster.sync.max-agents-per-node','cluster.sync.max-events-per-node','cluster.sync.remote-state-ttl-ms','cluster.sync.request-timeout-ms') and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true;
if v_ready<>11 then raise exception 'C3R2J_DOMAIN_DEFINITION_CLOSURE_INCOMPLETE expected=11 actual=%',v_ready; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('cluster.delivery-router.enabled','cluster.delivery-router.prefer-local','cluster.delivery-router.reject-duplicate-agents','cluster.delivery-router.request-timeout-ms','cluster.delivery-router.require-synced-remote-state','cluster.sync.enabled','cluster.sync.interval-ms','cluster.sync.max-agents-per-node','cluster.sync.max-events-per-node','cluster.sync.remote-state-ttl-ms','cluster.sync.request-timeout-ms') and config_set_key<>'RUNTIME/CLUSTER/SYSTEM') then raise exception 'C3R2J_CLUSTER_CONFIG_SET_KEY_MISMATCH'; end if;
if exists(select 1 from runtime_config_inventory_governance where configuration_key in ('cluster.delivery-router.enabled','cluster.delivery-router.prefer-local','cluster.delivery-router.reject-duplicate-agents','cluster.delivery-router.request-timeout-ms','cluster.delivery-router.require-synced-remote-state','cluster.sync.enabled','cluster.sync.interval-ms','cluster.sync.max-agents-per-node','cluster.sync.max-events-per-node','cluster.sync.remote-state-ttl-ms','cluster.sync.request-timeout-ms') and status in ('MIGRATED','LEGACY_RETIRED')) then raise exception 'C3R2J_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if;
end $$;
